# environment + epsilon check
import importlib, numpy as np
for m in ['numpy','scipy','sympy','matplotlib']:
    try:
        importlib.import_module(m); print(m, 'OK')
    except ImportError:
        print(m, 'MISSING')
print('eps =', np.finfo(float).eps)  # 2.22e-16: the atomic unit of error
# never: a == b. always: abs(a-b) < 1e-12.

# dual numbers: exact first derivatives by algebra
class Dual:
    def __init__(self, r, d=0.0): self.r, self.d = r, d
    def __add__(self, o): o = o if isinstance(o, Dual) else Dual(o)
        return Dual(self.r+o.r, self.d+o.d)
    def __mul__(self, o): o = o if isinstance(o, Dual) else Dual(o)
        return Dual(self.r*o.r, self.r*o.d + self.d*o.r)
# f(x)=x^2 at x=3: Dual(3,1)^2 -> Dual(9, 6): value 9, derivative 6. Exact!
